import{_ as l,o as p,c as a,a2 as t}from"./chunks/framework.CdvW4CUT.js";const c=JSON.parse('{"title":"第 5 章 EP (Expert Parallelism)","description":"","frontmatter":{},"headers":[],"relativePath":"parallelism/Expert-parallelism.md","filePath":"parallelism/Expert-parallelism.md"}'),r={name:"parallelism/Expert-parallelism.md"};function i(o,e,n,s,P,E){return p(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="第-5-章-ep-expert-parallelism" tabindex="-1">第 5 章 EP (Expert Parallelism) <a class="header-anchor" href="#第-5-章-ep-expert-parallelism" aria-label="Permalink to &quot;第 5 章 EP (Expert Parallelism)&quot;">​</a></h1><h2 id="_1-ep-的完整工作流程" tabindex="-1">1. EP 的完整工作流程 <a class="header-anchor" href="#_1-ep-的完整工作流程" aria-label="Permalink to &quot;1. EP 的完整工作流程&quot;">​</a></h2><p>假设 Token A 在 GPU 0 上，Router 选择了 Expert 2 和 Expert 5。</p><p>流程如下：</p><ol><li>GPU 0 先计算 Attention 和 Router。</li><li>Expert 2 在 GPU 0，本地计算。</li><li>Expert 5 在 GPU 1，因此将 Token A 的 hidden state 发送到 GPU 1。</li><li>GPU 1 使用 Expert 5 计算。</li><li>Expert 5 的输出返回 GPU 0。</li><li>GPU 0 按 Router 权重合并两个 Expert 的结果，继续后续计算。</li></ol><p>这里有两个我们专门澄清过的知识点。</p><p>第一：Router 不是只存在于 GPU 0。</p><p>在这个简化配置中，两张 GPU 都可以运行 Router。哪个 GPU 当前持有 Token 的 hidden state，就可以在当地计算路由决策。</p><p>第二：通信传输的是 Token 的激活数据，不是每次传 Expert 权重。</p><p>Expert 权重提前加载并常驻对应 GPU 的显存。</p><h2 id="_2-ep-的-load-balancing-负载均衡" tabindex="-1">2. EP 的 Load Balancing（负载均衡） <a class="header-anchor" href="#_2-ep-的-load-balancing-负载均衡" aria-label="Permalink to &quot;2. EP 的 Load Balancing（负载均衡）&quot;">​</a></h2><p>假设有 100 个 Tokens，其中 80 个都被路由到 GPU 0 上的 Expert 1。</p><p>那么：</p><ul><li>GPU 0 非常忙。</li><li>GPU 1 可能相对空闲。</li></ul><p>即使 GPU 1 有空闲算力，也不能随便处理 Expert 1 的 Tokens，因为它没有 Expert 1 的权重。</p><p>两种解决方式。</p><ol><li>Expert Replication</li></ol><p>把热门 Expert 复制到多张 GPU。</p><p>例如 Expert 1 同时放在 GPU 0 和 GPU 1。</p><p>那么 80 个 Tokens 可以分成两批，各自在一张 GPU 上计算。</p><p>代价是占用更多显存。</p><p>对比 TP：</p><ul><li>TP：两张 GPU 合作计算同一个 Expert 的一次运算。</li><li>Expert Replication：两张 GPU 都拥有完整 Expert，各自处理不同 Tokens。</li></ul><ol start="2"><li>Dynamic Expert Placement / Rebalancing</li></ol><p>根据运行中的负载情况，周期性调整 Expert 的放置。</p><blockquote><p>系统怎么知道哪个 Expert 更忙？</p></blockquote><p>两个指标：</p><ul><li>Router 的路由统计：每个 Expert 被分配了多少 Tokens。</li><li>实际执行指标：每个 Expert 的执行时间、等待情况，以及对应 GPU 的负载。</li></ul><p>系统可以据此识别热门 Experts，再决定是否需要复制或重新分布。</p>',29)])])}const d=l(r,[["render",i]]);export{c as __pageData,d as default};
